from pathlib import Path
import json,re,hashlib,sys
D=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path(__file__).resolve().parents[1];P=D.parents[1];A=D/'assets'
icon='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#112b47"/><stop offset="1" stop-color="#071625"/></linearGradient><radialGradient id="s" cx=".3" cy=".2"><stop stop-color="#d6ffff"/><stop offset=".4" stop-color="#59d5d4"/><stop offset=".75" stop-color="#216f92"/><stop offset="1" stop-color="#0b2f4e"/></radialGradient></defs><rect x="2" y="2" width="92" height="92" rx="24" fill="url(#bg)"/><path d="M10 73L45 56 86 75M45 56L64 18M45 56L12 32" stroke="#65e1d6" stroke-width="3" fill="none"/><path d="M14 31L42 53 66 20" stroke="#ffb284" stroke-width="3" fill="none"/><ellipse cx="51" cy="76" rx="25" ry="7" fill="#000" opacity=".3"/><circle cx="49" cy="52" r="23" fill="url(#s)"/><path d="M29 47Q36 27 55 32" fill="none" stroke="#fff" stroke-width="3" opacity=".7"/><circle cx="66" cy="19" r="4" fill="#ffd5a6"/><circle cx="13" cy="31" r="4" fill="#67e9df"/></svg>'''
banner='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 440" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sky" x2="1" y2=".8"><stop stop-color="#0b2037"/><stop offset=".55" stop-color="#102f45"/><stop offset="1" stop-color="#173f50"/></linearGradient><radialGradient id="glow"><stop stop-color="#4bd2c7" stop-opacity=".23"/><stop offset="1" stop-color="#4bd2c7" stop-opacity="0"/></radialGradient><radialGradient id="orb" cx=".32" cy=".22" r=".8"><stop stop-color="#e9ffff"/><stop offset=".16" stop-color="#a5e9e5"/><stop offset=".4" stop-color="#3ca6ac"/><stop offset=".7" stop-color="#1a5f81"/><stop offset="1" stop-color="#0a283f"/></radialGradient><linearGradient id="prism" x2="1" y2="1"><stop stop-color="#91d7dd" stop-opacity=".5"/><stop offset="1" stop-color="#245273" stop-opacity=".2"/></linearGradient><filter id="blur"><feGaussianBlur stdDeviation="11"/></filter><pattern id="grid" width="72" height="38" patternUnits="userSpaceOnUse"><path d="M0 38H72M72 0V38" fill="none" stroke="#93d6d4" stroke-opacity=".08"/></pattern></defs><rect width="1600" height="440" fill="url(#sky)"/><ellipse cx="1240" cy="195" rx="460" ry="310" fill="url(#glow)"/><path d="M520 440L1000 222 1600 325V440Z" fill="#163b4b"/><path d="M560 440L1030 235 1600 338V440Z" fill="url(#grid)"/><g fill="none" stroke="#70cfc9" stroke-opacity=".18"><path d="M650 440L1100 245M850 440L1180 260M1100 440L1270 278M1380 440L1410 303"/><path d="M770 344L1600 412M880 293L1600 351"/></g><ellipse cx="1230" cy="364" rx="170" ry="27" fill="#020d1c" opacity=".55" filter="url(#blur)"/><path d="M910 336L1013 139 1114 337Z" fill="url(#prism)" stroke="#8bd3dd" stroke-opacity=".45" stroke-width="2"/><path d="M1013 139L1040 328 1114 337" fill="#103750" fill-opacity=".5" stroke="#6fc7d1" stroke-opacity=".32"/><path d="M818 60L1065 264 1317 57" fill="none" stroke="#ffc18b" stroke-width="3" opacity=".84"/><path d="M1065 264L1410 354 1512 232" fill="none" stroke="#65e7da" stroke-width="2.5" opacity=".85"/><path d="M1065 264L1183 357 1490 359" fill="none" stroke="#76bdf2" stroke-width="1.5" opacity=".5"/><circle cx="1241" cy="241" r="116" fill="url(#orb)"/><path d="M1144 211Q1171 118 1257 137" fill="none" stroke="#d6ffff" stroke-width="5" opacity=".66"/><path d="M1171 323Q1255 374 1334 296" fill="none" stroke="#50d3d3" stroke-width="3" opacity=".3"/><path d="M1256 132Q1342 166 1333 262" fill="none" stroke="#e3ffff" stroke-width="1.5" opacity=".35"/><path d="M1260 353L1278 384 1204 381Z" fill="#64dbd2" opacity=".22" filter="url(#blur)"/><g fill="#b6e9e3"><circle cx="1065" cy="264" r="5"/><circle cx="1410" cy="354" r="4"/><circle cx="1512" cy="232" r="3"/><circle cx="922" cy="95" r="2" opacity=".4"/><circle cx="1440" cy="108" r="2" opacity=".5"/><circle cx="1373" cy="53" r="2" opacity=".4"/></g><path d="M1269 43L1365 56 1348 74 1257 61Z" fill="#ffe1b1" opacity=".9"/><path d="M1269 43L1365 56" stroke="#fff2d6" stroke-width="3"/><rect width="890" height="440" fill="url(#sky)" opacity=".2"/></svg>'''
(A/'identity.svg').write_text(icon,encoding='utf-8');(A/'banner.svg').write_text(banner,encoding='utf-8')
p=D/'index.html';s=p.read_text(encoding='utf-8')
s=s.replace('<h1>RTXDI Next</h1>','<h1>RTXPT Next</h1>').replace('<title>Basix Pathtracing · RTXDI Next</title>','<title>Basix Pathtracing · RTXPT Next</title>')
s=s.replace('The repository remains named RTXDI_Next.','The repository is named RTXPT_Next.').replace('Basix_Pathtracing / RTXDI_Next','Basix Pathtracing / RTXPT_Next')
s=re.sub(r'<details class="doc-header-settings"><summary>Display</summary><div data-doc-theme-host></div></details>','',s)
s=s.replace('assets/identity.svg"','assets/identity.svg?v='+hashlib.sha256(icon.encode()).hexdigest()[:10]+'"')
s=s.replace('<figure><img class="integration-map"','<figure tabindex="0" role="region" aria-label="Integration dependency map; scroll horizontally on narrow screens"><img class="integration-map"')
s=s.replace('<div class="doc-overview"><p class="doc-caption">','<div class="doc-overview doc-banner"><p class="doc-caption">',1)
# Keep the conceptual map outside the banner, so text and architecture stay readable.
m=re.search(r'(<div class="doc-overview doc-banner">)([\s\S]*?)(<figure>[\s\S]*?</figure>)(</div>)',s)
if m:s=s[:m.start()]+m[1]+m[2]+m[4]+m[3]+s[m.end():]
css='''<style data-rtxpt-brand>.doc-overview.doc-banner{display:block;position:relative;background:linear-gradient(90deg,#0b2037f5 0%,#0b2037dd 42%,#0b203722 82%),url('assets/banner.svg') center/cover no-repeat;padding:38px 34px;min-height:250px}.doc-banner h1{font-size:clamp(36px,4.8vw,60px);letter-spacing:-.045em}.doc-banner>p{max-width:620px;font-size:17px}.doc-banner .doc-caption{font-size:12px;letter-spacing:.14em;text-transform:uppercase}.doc-brand img{border-radius:10px}.doc-main>figure{margin:24px 0;overflow-x:auto}.doc-main>figure .integration-map{min-width:720px}.doc-banner+figure figcaption{font-size:13px;color:var(--doc-muted)}@media(max-width:700px){.doc-overview.doc-banner{min-height:210px;padding:24px;background-position:60% center}.doc-banner>p{max-width:90%;font-size:15px}.doc-banner h1{font-size:38px}}</style>'''
s=re.sub(r'<style data-rtxpt-brand>[\s\S]*?</style>','',s)
s=s.replace('</head>',css+'</head>')
p.write_text(s,encoding='utf-8')
for p in list(D.glob('*.md'))+[P/'README.md',P/'Benchmarks/README.md']:
    t=p.read_text(encoding='utf-8').replace('https://github.com/BasixMaster/RTXDI_Next','https://github.com/BasixMaster/RTXPT_Next')
    t=t.replace('The repository remains named RTXDI_Next.','The repository is named RTXPT_Next.').replace('# Basix Pathtracing · RTXDI Next','# Basix Pathtracing · RTXPT Next').replace('Basix_Pathtracing / RTXDI_Next','Basix Pathtracing / RTXPT_Next')
    p.write_text(t,encoding='utf-8')
v=P/'Benchmarks/versions.json';data=json.loads(v.read_text(encoding='utf-8'));data['repository']='BasixMaster/RTXPT_Next';v.write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8')
(D/'branding.json').write_text(json.dumps(dict(project='Basix Pathtracing',product='RTXPT Next',repository='BasixMaster/RTXPT_Next',banner='assets/banner.svg',icon='assets/identity.svg',rights='Original editable SVG artwork for this project; no third-party image assets.'),indent=2)+'\n',encoding='utf-8')
print(json.dumps(dict(project='Basix Pathtracing',title='RTXPT Next',repository='BasixMaster/RTXPT_Next')))
